function soloSpeciesPoolForFloor(floor){
 const biome=biomeForFloor(floor),unlocked=Object.values(SPECIES).filter(species=>species.fieldEncounter!==false&&!species.ultraRareEncounter&&!species.isAbyss&&!species.isTenGod&&!['深淵','十神'].includes(species.rarity)&&(species.minFloor??1)<=floor).sort((a,b)=>(a.minFloor??1)-(b.minFloor??1));
 if(!unlocked.length)return[SPECIES.slime];const nearby=unlocked.filter(species=>(species.minFloor??1)>=Math.max(1,floor-300)),candidates=nearby.length>=8?nearby:unlocked.slice(-24);
 return candidates.flatMap(species=>{const rarityWeight=SOLO_RARITY_WEIGHTS[species.rarity]??1,biomeWeight=biome.elements.includes(species.element)?(floor>=101?6:3):1;return Array.from({length:rarityWeight*biomeWeight},()=>species)});
}
function soloRandomSpeciesForFloor(floor,random){
 if(floor===1)return SPECIES.slime;if(floor>=2&&random()<.006)return SPECIES.baby_slime??SPECIES.slime;
 const pool=soloSpeciesPoolForFloor(floor).filter(species=>species.id!=="baby_slime");return pool[Math.floor(random()*pool.length)]??SPECIES.slime;
}
