const RANDOM_CIRCLE_SKILL_POOL=Object.freeze((()=>{const unique=new Map();for(const skill of Object.values(SKILLS??{}))if(skill?.id)unique.set(skill.id,skill);for(const skill of Object.values(ENDGAME_SKILLS??{}))if(skill?.id)unique.set(skill.id,skill);for(const speciesId of Object.keys(SPECIES??{}))for(const skill of buildIndividualSkillKit(speciesId)??[])if(skill?.id)unique.set(skill.id,skill);for(const boss of FLOOR_BOSS_CATALOG??[]){const skill=boss?.dedicatedWeapon?.skill??boss?.weaponSkill;if(skill?.id)unique.set(skill.id,skill)}return[...unique.values()]})());

function token(bytes=18){return randomBytes(bytes).toString("base64url")}
function roomCode(){const bytes=randomBytes(6);return Array.from(bytes,value=>ROOM_ALPHABET[value%ROOM_ALPHABET.length]).join("")}
function text(value,max=32){return String(value??"").replace(/[\u0000-\u001f\u007f]/g,"").trim().slice(0,max)}
function number(value,min,max,fallback=min){const parsed=Number(value);return Number.isFinite(parsed)?Math.max(min,Math.min(max,parsed)):fallback}
function integer(value,min,max,fallback=min){return Math.round(number(value,min,max,fallback))}
function bool(value){return Boolean(value)}
function skillCleanses(skill){return Boolean(skill&&skill.cleanse)}
function effectiveEvasion(entity){return Math.max(0,Math.min(75,(Number(entity?.stats?.evasion??entity?.evasion)||0)*(1+effectValue(entity,"evasionUp")-effectValue(entity,"evasionDown"))))}
function hitLands(attacker,target,random,guaranteed=false){if(guaranteed)return true;const accuracy=Math.max(20,Math.min(180,(Number(attacker?.stats?.accuracy??attacker?.accuracy)||100)*(1+effectValue(attacker,"accuracyUp")-effectValue(attacker,"accuracyDown")))),dodge=Math.max(0,Math.min(75,effectiveEvasion(target)-(accuracy-100)*.5));return random()<Math.max(.08,Math.min(.98,1-dodge/100))}
function fourLrAlive(players){const alive=new Set(Object.values(players??{}).filter(player=>player.hp>0).map(player=>player.speciesId));return FOUR_LR_IDS.every(id=>alive.has(id))}
function pointKey(point){return`${point.x},${point.y}`}
function hashText(value){let hash=2166136261;for(const char of String(value))hash=Math.imul(hash^char.charCodeAt(0),16777619);return hash>>>0}
function seededRandom(seed){let state=seed>>>0;return()=>{state+=0x6D2B79F5;let value=state;value=Math.imul(value^value>>>15,value|1);value^=value+Math.imul(value^value>>>7,value|61);return((value^value>>>14)>>>0)/4294967296}}
// The offline exploration generator uses this LCG.  Online rooms use the
// host's saved floor seed so the same floor has the same layout and chests.
function offlineRandom(seed){let state=seed>>>0;return()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296}}
function shuffle(list,rng){for(let index=list.length-1;index>0;index--){const swap=Math.floor(rng()*(index+1));[list[index],list[swap]]=[list[swap],list[index]]}return list}
